   577	/// manifest was complete, from what was left of the map of the manifest —
   578	/// and a need takes its entry out of that map, and needs arrive while the
   579	/// manifest is still going. Past the first batch of needs (128 files) a
   580	/// move delivered everything, left at its source whatever had been asked
   581	/// for early, said `it is not a file the move sent` of each, and exited
   582	/// 1. Found measuring a move of 20,000 files, 2026-11-21: 3,840 left.
   583	#[test]
   584	fn a_move_of_many_files_removes_every_one_it_delivered() {
   585	    let ctx = TestContext::new();
   586	    let tree = ctx.module_dir.join("tree");
   587	    let (dirs, files) = (10, 100);
   588	    for d in 0..dirs {
   589	        let dir = tree.join(format!("d{d:02}"));
   590	        fs::create_dir_all(&dir).unwrap();
   591	        for f in 0..files {
   592	            fs::write(dir.join(format!("f{f:03}")), format!("{d}/{f}")).unwrap();
   593	        }
   594	    }
   595	    let landed = ctx.workspace.join("landed");
   596	    let source = format!("127.0.0.1:{}:/test/tree/", ctx.daemon_port);
   597	    let (code, said) = blit(
   598	        &ctx,
   599	        &["move", "-y", &source, &format!("{}/", landed.display())],
   600	    );
   601	    assert_eq!(code, Some(0), "{said}");
   602	    let count = |root: &std::path::Path| -> usize {
   603	        fn walk(dir: &std::path::Path, count: &mut usize) {
   604	            for entry in fs::read_dir(dir).into_iter().flatten().flatten() {
   605	                if entry.file_type().is_ok_and(|kind| kind.is_dir()) {
   606	                    walk(&entry.path(), count);
   607	                } else {
   608	                    *count += 1;
   609	                }
   610	            }
   611	        }
   612	        let mut count = 0;
   613	        walk(root, &mut count);
   614	        count
   615	    };
   616	    assert_eq!(count(&landed), dirs * files, "everything landed\n{said}");
   617	    assert_eq!(
   618	        fs::read(landed.join("d09/f099")).unwrap(),
   619	        b"9/99",
   620	        "{said}"
   621	    );
   622	    assert_eq!(
   623	        count(&tree),
   624	        0,
   625	        "and nothing delivered stays at the source\n{said}"
   626	    );
   627	    assert!(
   628	        !tree.join("d00").exists(),
   629	        "nor the directories it emptied\n{said}"
   630	    );
   631	}
   632	
   633	/// cr-uv5-4: a move of two names of one text removes both once both have
   634	/// landed. A source holding `dup` and the byte `FF`, and `dup` and
   635	/// U+FFFD: the end that writes takes the first and refuses the second,
   636	/// and the retry lands it. The first session's account struck what was
   637	/// refused by its text AND its bytes — the file that had LANDED bears
   638	/// that text as its name, was struck with it, and stayed at the source:
   639	/// the reviewer saw `dup` and U+FFFD left behind, and exit 1.
   640	#[cfg(unix)]
   641	#[test]
   642	fn a_move_of_two_names_of_one_text_removes_both() {
   643	    use std::ffi::OsStr;
   644	    use std::os::unix::ffi::OsStrExt;
   645	
   646	    let ctx = TestContext::new();
   647	    let tree = ctx.module_dir.join("tree");
   648	    fs::create_dir_all(&tree).unwrap();
   649	    let raw = OsStr::from_bytes(b"dup\xff");
   650	    if fs::write(tree.join(raw), b"named by a byte").is_err() {
   651	        eprintln!("this filesystem refuses a name that is not text: nothing to tell apart");
   652	        return;
   653	    }
   654	    fs::write(tree.join("dup\u{fffd}"), b"named by the character").unwrap();
   655	    fs::write(tree.join("plain.txt"), b"beside them").unwrap();
   656	    let landed = ctx.workspace.join("landed");
   657	    let source = format!("127.0.0.1:{}:/test/tree/", ctx.daemon_port);
   658	    let (code, said) = blit(
   659	        &ctx,
   660	        &[
   661	            "move",
   662	            "-y",
   663	            "--retries",
   664	            "1",
   665	            "--diagnostics-no-retry-wait",
   666	            &source,
   667	            &format!("{}/", landed.display()),
   668	        ],
   669	    );
   670	    assert_eq!(code, Some(0), "{said}");
   671	    assert_eq!(
   672	        fs::read(landed.join(raw)).unwrap(),
   673	        b"named by a byte",
   674	        "{said}"
   675	    );
   676	    assert_eq!(
   677	        fs::read(landed.join("dup\u{fffd}")).unwrap(),
   678	        b"named by the character",
   679	        "{said}"
   680	    );
   681	    let left: Vec<_> = fs::read_dir(&tree)
   682	        .map(|entries| entries.flatten().map(|entry| entry.file_name()).collect())
   683	        .unwrap_or_default();
   684	    assert!(left.is_empty(), "left at the source: {left:?}\n{said}");
   685	}
   686	
   687	/// cr-uv5-3: a move takes every name of a file that has several. Both
   688	/// names of one file arrived, and the removal — which takes a file only
   689	/// while it is the file that was sent — refused the second: taking the
   690	/// first name had changed the file, as taking a name does. The reviewer
   691	/// saw one name left at the source, and exit 1.
   692	#[cfg(unix)]
   693	#[test]
   694	fn a_move_takes_every_name_of_a_file_with_several() {
   695	    let ctx = TestContext::new();
   696	    let tree = ctx.module_dir.join("tree");
   697	    fs::create_dir_all(tree.join("sub")).unwrap();
   698	    fs::write(tree.join("first.txt"), b"one file, three names").unwrap();
   699	    fs::hard_link(tree.join("first.txt"), tree.join("second.txt")).unwrap();
   700	    fs::hard_link(tree.join("first.txt"), tree.join("sub/third.txt")).unwrap();
   701	    fs::write(tree.join("alone.txt"), b"another").unwrap();
   702	    let landed = ctx.workspace.join("landed");
   703	    let source = format!("127.0.0.1:{}:/test/tree/", ctx.daemon_port);
   704	    let (code, said) = blit(
   705	        &ctx,
   706	        &["move", "-y", &source, &format!("{}/", landed.display())],
   707	    );
   708	    assert_eq!(code, Some(0), "{said}");
   709	    for name in ["first.txt", "second.txt", "sub/third.txt"] {
   710	        assert_eq!(
   711	            fs::read(landed.join(name)).unwrap(),
   712	            b"one file, three names",
   713	            "{name}\n{said}"
   714	        );
   715	    }
   716	    assert_eq!(fs::read(landed.join("alone.txt")).unwrap(), b"another");
   717	    let left: Vec<_> = fs::read_dir(&tree)
   718	        .map(|entries| entries.flatten().map(|entry| entry.file_name()).collect())
   719	        .unwrap_or_default();
   720	    assert!(left.is_empty(), "left at the source: {left:?}\n{said}");
   721	}
   722	
   723	/// cr-uv5-2: a move never removes bytes nobody was sent. A file is
   724	/// rewritten by another hand — as many bytes, its time put back — while
   725	/// the move is still writing its manifest: after the file was read (here,
   726	/// hashed: the destination already holds its first bytes under another
   727	/// time, so by `--checksum` nothing of it is sent) and before the
   728	/// manifest's end, which files that take a while to hash put off.
   729	///
   730	/// The account of what a move may remove was written at the manifest's
   731	/// end, from a second look at each file, and that look took the rewritten
   732	/// file for the one that had been hashed: it went from the source with
   733	/// exit 0, and its bytes were nowhere. The account now holds each file as
   734	/// the walk first saw it, so a file changed after that look stays.
   735	///
   736	/// What is asserted holds whenever the rewrite lands: the rewritten bytes
   737	/// are at the source still, or at the destination. Against the code
   738	/// before this fix it fails when the rewrite lands between the hash and
   739	/// the manifest's end — which the sizes here make most of a second wide.
   740	#[cfg(unix)]
   741	#[test]
   742	fn a_move_never_removes_bytes_nobody_was_sent() {
   743	    let ctx = TestContext::new();
   744	    let tree = ctx.module_dir.join("tree");
   745	    let landed = ctx.workspace.join("landed");
   746	    for at in [&tree, &landed] {
   747	        fs::create_dir_all(at).unwrap();
   748	        // A while to hash, and nothing to store: all holes.
   749	        for n in 0..6 {
   750	            fs::File::create(at.join(format!("big{n}.bin")))
   751	                .and_then(|big| big.set_len(512 * 1024 * 1024))
   752	                .unwrap();
   753	        }
   754	        // Made last, and first by name: a walk that reads a directory
   755	        // newest first meets it first, and so does one that reads by name.
   756	        fs::write(at.join("a-small.txt"), b"1234").unwrap();
   757	    }
   758	    // Another time at the destination: only the checksum says the two are
   759	    // one file.
   760	    filetime::set_file_mtime(
   761	        landed.join("a-small.txt"),
   762	        filetime::FileTime::from_unix_time(1_000_000_000, 0),
   763	    )
   764	    .unwrap();
   765	    let small = tree.join("a-small.txt");
   766	    let written = filetime::FileTime::from_last_modification_time(&fs::metadata(&small).unwrap());
   767	
   768	    let mover = {
   769	        let (cli, config) = (ctx.cli_bin.clone(), ctx.config_dir.clone());
   770	        let source = format!("127.0.0.1:{}:/test/tree/", ctx.daemon_port);
   771	        let destination = format!("{}/", landed.display());
   772	        std::thread::spawn(move || {
   773	            let mut cmd = Command::new(cli);
   774	            cmd.arg("--config-dir")
   775	                .arg(config)
   776	                .args(["move", "-y", "--checksum"])
   777	                .arg(source)
   778	                .arg(destination);
   779	            run_with_timeout(cmd, Duration::from_secs(180))
   780	        })
   781	    };
   782	    std::thread::sleep(Duration::from_millis(250));
   783	    // Another hand: as many bytes, and the time put back.
   784	    fs::write(&small, b"4321").unwrap();
   785	    filetime::set_file_mtime(&small, written).unwrap();
   786	    let output = mover.join().expect("the move");
   787	    let said = format!(
   788	        "exit {:?}\n{}{}",
   789	        output.status.code(),
   790	        String::from_utf8_lossy(&output.stdout),
   791	        String::from_utf8_lossy(&output.stderr)
   792	    );
   793	
   794	    let at_source = fs::read(&small).ok();
   795	    let at_destination = fs::read(landed.join("a-small.txt")).unwrap();
   796	    assert!(
   797	        at_source.as_deref() == Some(&b"4321"[..]) || at_destination == b"4321",
   798	        "the rewritten bytes are nowhere: gone from the source, and the destination holds \
   799	         {:?}\n{said}",
   800	        String::from_utf8_lossy(&at_destination)
   801	    );
   802	    match at_source {
   803	        // Left where it was: said, and the move did not end well.
   804	        Some(_) => {
   805	            assert_eq!(output.status.code(), Some(1), "{said}");
   806	            assert!(said.contains("a-small.txt"), "{said}");
   807	        }
   808	        None => assert_eq!(output.status.code(), Some(0), "{said}"),
   809	    }
   810	    // What was not touched went, either way.
   811	    for n in 0..6 {
   812	        assert!(!tree.join(format!("big{n}.bin")).exists(), "big{n}\n{said}");
   813	    }
   814	}
